<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/design.css"><title>Notifications</title></head><body class="dashboard-page"><header class="dashboard-header"><a href="/">SUN SON SOLAR</a><span><?= esc(session()->get('name')) ?></span><a href="/logout">Logout</a></header><main class="section"><h1>Notifications</h1><div class="card"><?php foreach($items as $n):?><article><h3><?= esc($n['title']) ?></h3><p><?= esc($n['message']) ?></p></article><?php endforeach;?><?php if(!$items):?><p>No notifications.</p><?php endif;?></div></main><script src="/js/main.js"></script></body></html>